import openpyxl, re
wb = openpyxl.load_workbook('1_54590_answer_double_counting_3019_input.xlsx')
ws = wb['HR ']
for row in ws.iter_rows(min_row=1, max_row=37):
    for c in row:
        if isinstance(c.value, str) and c.value.startswith('='):
            v = c.value[1:]
            # find SUM/SOMMA function call parentheses
            for m in re.finditer(r'SUM\(([^()]*)\)', v.upper()):
                args = m.group(1)
                parts = [p.strip() for p in args.split(',')]
                # check duplicates
                from collections import Counter
                cnt = Counter(parts)
                dups = {p:n for p,n in cnt.items() if n>1}
                if dups:
                    print(c.coordinate, repr(c.value), '->', dups)
EOF
